import{_ as e,o as a,c as r,a4 as i}from"./chunks/framework.9tZL7ZIQ.js";const m=JSON.parse('{"title":"沃尔特·斯科特 (Walter Scott Jr.)","description":"","frontmatter":{},"headers":[],"relativePath":"04_people/沃尔特·斯科特.md","filePath":"04_people/沃尔特·斯科特.md"}'),l={name:"04_people/沃尔特·斯科特.md"};function d(o,t,n,h,s,c){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="沃尔特·斯科特-walter-scott-jr" tabindex="-1">沃尔特·斯科特 (Walter Scott Jr.) <a class="header-anchor" href="#沃尔特·斯科特-walter-scott-jr" aria-label="Permalink to &quot;沃尔特·斯科特 (Walter Scott Jr.)&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>全名</td><td>Walter Scott Jr.</td></tr><tr><td>出生</td><td>1931年，奥马哈，内布拉斯加州</td></tr><tr><td>逝世</td><td>2023年</td></tr><tr><td>职业</td><td>企业家、投资人</td></tr><tr><td>公司</td><td>Peter Kiewit Sons&#39;、Level 3 Communications</td></tr><tr><td>伯克希尔职务</td><td>董事</td></tr></tbody></table><h2 id="职业生涯" tabindex="-1">职业生涯 <a class="header-anchor" href="#职业生涯" aria-label="Permalink to &quot;职业生涯&quot;">​</a></h2><h3 id="早年与-peter-kiewit-sons" tabindex="-1">早年与 Peter Kiewit Sons&#39; <a class="header-anchor" href="#早年与-peter-kiewit-sons" aria-label="Permalink to &quot;早年与 Peter Kiewit Sons&#39;&quot;">​</a></h3><ul><li>奥马哈本地企业家，出生于传奇建筑巨头 Peter Kiewit 家族</li><li>参与创建并执掌 <strong>Peter Kiewit Sons&#39;</strong>——美国最成功的私营建筑企业之一</li><li>在奥马哈商界建立了卓越声誉</li></ul><h3 id="level-3-communications" tabindex="-1">Level 3 Communications <a class="header-anchor" href="#level-3-communications" aria-label="Permalink to &quot;Level 3 Communications&quot;">​</a></h3><ul><li>担任 <strong>Level 3 Communications</strong> 董事长</li><li>公司是全球领先的通信基础设施提供商</li><li>展示了在资本密集型基础设施建设领域的运营能力</li></ul><h2 id="与巴菲特的友谊" tabindex="-1">与巴菲特的友谊 <a class="header-anchor" href="#与巴菲特的友谊" aria-label="Permalink to &quot;与巴菲特的友谊&quot;">​</a></h2><h3 id="奥马哈老乡" tabindex="-1">奥马哈老乡 <a class="header-anchor" href="#奥马哈老乡" aria-label="Permalink to &quot;奥马哈老乡&quot;">​</a></h3><ul><li>与巴菲特同为奥马哈人，多年密友</li><li>同为奥马哈商界和慈善界的核心人物</li><li>两家关系密切，是巴菲特信任的圈内人</li></ul><h3 id="关键引荐-midamerican-energy-1999年" tabindex="-1">关键引荐：MidAmerican Energy（1999年） <a class="header-anchor" href="#关键引荐-midamerican-energy-1999年" aria-label="Permalink to &quot;关键引荐：MidAmerican Energy（1999年）&quot;">​</a></h3><blockquote><p>斯科特最重要的贡献之一——将 <strong>MidAmerican Energy</strong> 引荐给巴菲特，直接促成了伯克希尔史上最重要的收购之一。</p></blockquote><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>引荐时间</td><td>1999年</td></tr><tr><td>引荐人</td><td>沃尔特·斯科特</td></tr><tr><td>当时CEO</td><td>大卫·索科尔（David Sokol）</td></tr><tr><td>收购完成</td><td>2000年</td></tr><tr><td>意义</td><td>伯克希尔能源板块的核心资产</td></tr></tbody></table><ul><li>斯科特以个人信誉为 MidAmerican 的管理层背书</li><li>让巴菲特对这家公司和团队建立了信任</li><li>这笔收购后来成为伯克希尔最成功的公用事业投资</li><li>收购后 <a href="/04_people/大卫·索科尔">大卫·索科尔</a> 担任 CEO，后由 <a href="/04_people/格雷格·阿贝尔">格雷格·阿贝尔</a> 全面接手</li><li>如今 <a href="/03_companies/中美能源">中美能源</a>（MidAmerican Energy Holdings）已是 <a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a> 旗下最重要的公用事业平台</li></ul><h2 id="伯克希尔董事角色" tabindex="-1">伯克希尔董事角色 <a class="header-anchor" href="#伯克希尔董事角色" aria-label="Permalink to &quot;伯克希尔董事角色&quot;">​</a></h2><ul><li>长期担任 <a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a> 董事</li><li>在董事会中代表奥马哈本地商业视角</li><li>参与公司重大决策</li><li>与巴菲特有深厚的个人信任基础</li></ul><h2 id="经典语录" tabindex="-1">经典语录 <a class="header-anchor" href="#经典语录" aria-label="Permalink to &quot;经典语录&quot;">​</a></h2><blockquote><p>&quot;奥马哈是我所知最适宜做生意的城市，而 Walter 是这座城市最值得信赖的商人之一。&quot; —— 巴菲特</p></blockquote><h2 id="商业成就" tabindex="-1">商业成就 <a class="header-anchor" href="#商业成就" aria-label="Permalink to &quot;商业成就&quot;">​</a></h2><table tabindex="0"><thead><tr><th>公司/领域</th><th>成就</th></tr></thead><tbody><tr><td>Peter Kiewit Sons&#39;</td><td>全球顶级私营建筑企业</td></tr><tr><td>Level 3 Communications</td><td>通信基础设施巨头</td></tr><tr><td>MidAmerican Energy</td><td>引荐给伯克希尔，创造数百亿美元价值</td></tr><tr><td>慈善事业</td><td>奥马哈多项公益事业支持者</td></tr></tbody></table><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>2000, 2001, 2003</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a> - 他所服务的公司</li><li><a href="/03_companies/中美能源">中美能源</a> - 他引荐给巴菲特的公司</li><li><a href="/04_people/大卫·索科尔">大卫·索科尔</a> - MidAmerican 时任 CEO，引荐时的重要搭档</li><li><a href="/04_people/格雷格·阿贝尔">格雷格·阿贝尔</a> - MidAmerican 现任董事长兼CEO，巴菲特接班人候选</li></ul><hr><p><em>最后更新：2026-04-12</em></p><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search?q=沃尔特·斯科特在1999年股东信中的原话">1999年：完整翻译|/01_letters/1999年/翻译</a></li><li><a href="/search?q=沃尔特·斯科特在1997年股东信中的原话">1997年：完整翻译|/01_letters/1997年/翻译</a></li><li><a href="/search?q=沃尔特·斯科特在1963年股东信中的原话">1963年：完整翻译|/01_letters/1963年/翻译</a></li><li><a href="/search?q=沃尔特·斯科特在1964年股东信中的原话">1964年：完整翻译|/01_letters/1964年/翻译</a></li><li><a href="/search?q=沃尔特·斯科特在2006年股东信中的原话">2006年：完整翻译|/01_letters/2006年/翻译</a></li></ul>',30)])])}const b=e(l,[["render",d]]);export{m as __pageData,b as default};
